function genealogyMemberPopup(){const id=state.selectedGenealogyMember;if(!id)return '';const members=state.data?.members||[],member=members.find(x=>x.id===id);if(!member)return '';const admin=state.user.role==='admin',downline=new Set([member.id]);let again=true;while(again){again=false;for(const x of members){if(downline.has(matrixParentOf(x))&&!downline.has(x.id)){downline.add(x.id);again=true}}}const current=matrixParentOf(member)||'',parents=members.filter(x=>x.role==='member'&&!downline.has(x.id)&&(x.status==='Active'||x.id===current)&&members.filter(y=>y.id!==member.id&&matrixParentOf(y)===x.id).length<5),options=parents.map(x=>`<option value="${esc(x.id)}" ${x.id===(state.matrixPrefillParent||current)?'selected':''}>${esc(x.name)} · ${esc(x.id)} · ${5-members.filter(y=>y.id!==member.id&&matrixParentOf(y)===x.id).length} open</option>`).join('');return `<div class="gene-popup-backdrop" data-close-gene-backdrop><section class="gene-popup" role="dialog" aria-modal="true" aria-labelledby="gene-popup-title"><button type="button" class="gene-popup-close" data-close-gene aria-label="Close member details">×</button><span class="matrix-kicker">MEMBER DETAILS</span><h2 id="gene-popup-title">${esc(member.name)}</h2><div class="gene-popup-facts"><div><small>Member ID</small><strong>${esc(member.id)}</strong></div><div><small>Username</small><strong>${esc(member.username)}</strong></div><div><small>Status</small><strong>${esc(member.status)}</strong></div><div><small>Joined</small><strong>${esc(member.joined||'—')}</strong></div><div><small>Email</small><strong>${esc(member.email||'—')}</strong></div><div><small>Commission wallet</small><strong>${money(member.wallet||0)}</strong></div><div><small>Total wallet balance</small><strong>${money((Number(member.wallet)||0)+(Number(member.paymentBalance)||0))}</strong></div><div><small>Direct positions filled</small><strong>${members.filter(x=>matrixParentOf(x)===member.id).length} / 5</strong></div><div><small>Member head</small><strong>${esc(members.find(x=>x.id===matrixParentOf(member))?.name||'Primary head')}</strong></div></div>${admin?`<div class="gene-popup-divider"></div><h3>Change member head</h3><p class="help-copy">The selected head is both this member’s genealogy parent and referral sponsor.</p><form id="gene-move-form"><input type="hidden" name="id" value="${esc(member.id)}"><div class="field"><label for="gene-head-reference">Find member head by referral link, ID or username</label><div class="input-action"><input id="gene-head-reference" placeholder="Paste referral link or enter member ID"><button type="button" class="btn outline" data-resolve-gene-head>Find</button></div><small id="gene-head-reference-hint" class="help-copy">Choose a valid member head below, or find one by reference.</small></div><div class="field"><label for="gene-matrix-parent">Member head</label><select name="matrixParent" id="gene-matrix-parent"><option value="">No head / top-level</option>${options}</select></div><div id="gene-move-error" class="product-form-message" role="alert" hidden></div><div class="action-row"><button class="btn teal" type="button" data-save-gene-placement>Save new position</button><button type="button" class="btn outline" data-edit-member="${esc(member.id)}">Edit all details</button><button type="button" class="btn red" data-delete-member="${esc(member.id)}" data-delete-name="${esc(member.name)}">Delete member</button></div></form>`:`<p class="help-copy">Contact an administrator to change account details or placement.</p>`}</section></div>`}
function genePage(){state.treeMode='matrix';const emptyAdmin=state.user.role==='admin'&&!memberRows().length;return `<section class="card"><div class="card-head"><div><h2>5 × 5 Member Genealogy</h2><p>Explore your member network by matrix level. Drag to pan and use zoom controls for larger teams.</p></div><span class="pill">${state.user.role==='admin'?'ADMIN VIEW':'YOUR NETWORK'}</span></div>${emptyAdmin?`<div class="alert">Your matrix network is empty. Create the first member as the top-level root, then add people to matrix positions.</div><button class="btn teal" data-page="add-member">＋ Create first member</button>`:`${matrixTree()}${genealogyMemberPopup()}`}</section>`}
function filters(){return `<div class="filter"><input id="search" value="${esc(state.search)}" placeholder="Search by name, ID or username"><select id="status-filter"><option>All</option><option ${state.filter==='Active'?'selected':''}>Active</option><option ${state.filter==='Pending'?'selected':''}>Pending</option><option ${state.filter==='Inactive'?'selected':''}>Inactive</option></select></div>`}
function productEditor(){
 if(state.user.role!=='admin')return `<div class="section-title"><h1>Product editor</h1><p>Administrator access is required.</p></div>`;
 const p=(state.data.products||[]).find(x=>x.id===state.editProductId)||null,previewImage=p?.imageData||p?.imageUrl||'';
 return `<div class="section-title section-title-action"><div><h1>${p?'Edit product':'Add product'}</h1><p>${p?'Update the product listing and its store image.':'Create a product listing for the member store.'}</p></div><button class="btn outline" data-page="products">← Back to catalogue</button></div><form id="product-form"><input type="hidden" name="id" value="${esc(p?.id||'')}"><input type="hidden" name="imageData" id="product-image-data" value="${esc(p?.imageData||'')}"><input type="hidden" name="imageUrl" id="product-image-url" value="${esc(p?.imageUrl||'')}"><div class="product-editor-grid"><section class="card product-edit-card"><div class="card-head"><div><h2>Product information</h2><p>Keep names, prices, and stock accurate.</p></div><span class="pill">${p?'EDITING':'NEW LISTING'}</span></div><div class="form-row"><div class="field"><label for="product-name">Product name</label><input id="product-name" name="name" required minlength="2" maxlength="100" value="${esc(p?.name||'')}" placeholder="e.g. Wireless headphones"></div><div class="field"><label for="product-sku">SKU / item code</label><input id="product-sku" name="sku" maxlength="60" value="${esc(p?.sku||'')}" placeholder="Optional stock code"></div></div><div class="form-row"><div class="field"><label for="product-category">Category</label><input id="product-category" name="category" maxlength="60" value="${esc(p?.category||'General')}" placeholder="Electronics"></div><div class="field"><label for="product-brand">Brand</label><input id="product-brand" name="brand" maxlength="80" value="${esc(p?.brand||'')}" placeholder="Brand name"></div></div><div class="field"><label for="product-description">Description</label><textarea id="product-description" name="description" rows="5" maxlength="1000" placeholder="Add product details members should know">${esc(p?.description||'')}</textarea><small class="field-hint">Up to 1,000 characters.</small></div><div class="form-row"><div class="field"><label for="product-price">Price (INR)</label><div class="input-prefix"><span>₹</span><input id="product-price" name="price" type="number" required min="0" max="100000000" step="0.01" value="${Number(p?.price)||0}"></div></div><div class="field"><label for="product-stock">Available stock</label><input id="product-stock" name="stock" type="number" required min="0" max="1000000" step="1" value="${Number(p?.stock)||0}"></div></div><label class="product-active-toggle"><span><strong>Visible in member store</strong><small>Turn off to hide this item while keeping its order history.</small></span><input type="checkbox" name="active" value="true" ${p?.active===false?'':'checked'}></label><div id="product-form-message" class="product-form-message" role="alert" hidden></div><div class="action-row product-form-actions"><button class="btn teal" type="submit" data-save-product>${p?'Save product changes':'Create product'}</button><button class="btn outline" type="button" data-page="products">Cancel</button></div></section><aside class="card product-image-card"><div class="card-head"><div><h2>Product image</h2><p>Upload a clear square or landscape photo.</p></div></div><div class="product-image-preview" id="product-image-preview">${previewImage?`<img src="${esc(previewImage)}" alt="${esc(p?.name||'Product')} preview">`:'<div class="product-image-placeholder"><span>▧</span><strong>Image preview</strong><small>JPG, PNG or WebP</small></div>'}</div><div class="field crop-ratio-field"><label for="product-image-ratio">Image ratio</label><select id="product-image-ratio" name="imageRatio">${[['1/1','Square · 1:1'],['4/3','Standard · 4:3'],['3/2','Landscape · 3:2'],['16/9','Wide · 16:9']].map(([v,l])=>`<option value="${v}" ${(p?.imageRatio||'1/1')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="product-cropper" id="product-cropper" hidden><section class="cropper-dialog"><div class="cropper-head"><span class="cropper-kicker">IMAGE EDITOR</span><strong>Position and crop</strong><small>Drag to move the image. Use zoom to frame the product.</small></div><label class="crop-ratio-field cropper-ratio" for="product-crop-ratio">Crop ratio<select id="product-crop-ratio"><option value="1/1">Square · 1:1</option><option value="4/3">Standard · 4:3</option><option value="3/2">Landscape · 3:2</option><option value="16/9">Wide · 16:9</option></select></label><div class="cropper-canvas-wrap"><canvas id="product-crop-canvas" aria-label="Drag image to frame the crop"></canvas></div><label class="crop-zoom-label" for="product-crop-zoom">Zoom <input id="product-crop-zoom" type="range" min="1" max="3" step="0.01" value="1"></label><div class="cropper-actions"><button type="button" class="btn outline" data-cancel-product-crop>Cancel</button><button type="button" class="btn teal" data-apply-product-crop>Apply crop</button></div></section></div><label for="product-image-file" class="btn outline product-upload-button">Choose image</label><input id="product-image-file" type="file" accept="image/png,image/jpeg,image/webp" hidden><button type="button" class="link-button product-remove-image" data-remove-product-image>Remove image</button><p class="field-hint">Images are resized and compressed in your browser before being stored locally.</p></aside></div></form>`
}
function pageContent(){const d=state.data||{};switch(state.page){case'dashboard':return dashboard();case'members':{const ms=memberRows().filter(m=>(state.filter==='All'||m.status===state.filter)&&(!state.search||`${m.name} ${m.id} ${m.username}`.toLowerCase().includes(state.search.toLowerCase())));return `<div class="section-title section-title-action"><div><h1>Manage members</h1><p>Review accounts and member status.</p></div><button class="btn teal" data-page="add-member">＋ Add member</button></div><section class="card">${filters()}${memberTable(ms)}</section>`}case'add-member':case'edit-member':case'requests':case'readme':case'commission':return extraPage(state.page);case'matrix-calculator':return matrixCalculator();case'genealogy':return genePage();case'member-payments':case'team-payments':return memberPaymentsPage();case'product-editor':return productEditor();case'store':return `<div class="section-title"><h1>Member store</h1><p>Browse products listed by your business.</p></div><div class="alert">Orders are recorded in this workspace only. No payment is collected.</div><div class="product-grid">${(d.products||[]).map((p,i)=>`<article class="product"><div class="product-top" ${(p.imageData||p.imageUrl)?`style="aspect-ratio:${esc(p.imageRatio||'4/3')};height:auto"`:''}>${(p.imageData||p.imageUrl)?`<img src="${esc(p.imageData||p.imageUrl)}" alt="${esc(p.name)}">`:p.category==='Electronics'?['🎧','⌚','🔊','🔋','🔌','🎧'][Math.max(0,i-3)%6]:['✦','◈','▣'][i%3]}</div><div class="product-body"><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${p.stock} in stock</p><div class="product-bottom"><strong>${money(p.price)}</strong><button class="btn teal" data-order="${p.id}">Place order</button></div></div></article>`).join('')}</div>`;case'orders':case'sales':{const rows=d.orders||[];return `<div class="section-title"><h1>${state.page==='sales'?'Sales history':state.user.role==='admin'?'All orders':'My orders'}</h1><p>${state.page==='sales'||state.user.role==='admin'?'Orders across all members.':'Your product order history.'}</p></div><section class="card">${filters()}${table(rows.filter(o=>!state.search||`${o.id} ${o.productName}`.toLowerCase().includes(state.search.toLowerCase())),[{label:'Order',key:'id'},{label:'Member',render:o=>esc((d.members||[]).find(m=>m.id===o.memberId)?.name||state.user.name)},{label:'Product',render:o=>`<strong>${esc(o.productName)}</strong>`},{label:'Date',key:'date'},{label:'Amount',render:o=>`<strong>${money(o.amount)}</strong>`},{label:'Status',render:o=>badge(o.status)},{label:'Edit',render:o=>state.user.role==='admin'?`<button class="btn outline" data-edit-order="${esc(o.id)}">Edit</button>`:badge(o.status)}])}</section>`}case'transactions':{const rows=d.transactions||[];return `<div class="section-title"><h1>${state.user.role==='admin'?'Transaction history':'Sending &amp; receiving transactions'}</h1><p>${state.user.role==='admin'?'Complete ledger for all members.':'Your transfers and transactions for members you directly head.'}</p></div><section class="card">${filters()}${table(rows.filter(t=>!state.search||`${t.id} ${t.description} ${t.type} ${transactionDirection(t)}`.toLowerCase().includes(state.search.toLowerCase())),[{label:'Date',key:'date'},{label:'Transaction ID',key:'id'},{label:'From / To',render:t=>`<strong>${esc(transactionDirection(t))}</strong>`},{label:'Description',render:t=>`<strong>${esc(t.description)}</strong>`},{label:'Type',key:'type'},{label:'Amount',render:t=>{const amount=transactionAmountForViewer(t);return `<strong class="${amount>0?'positive':'negative'}">${amount>0?'+':''}${money(amount)}</strong>`}},{label:'Status',render:t=>badge(transactionStatusForViewer(t))},{label:'Edit',render:t=>state.user.role==='admin'?`<button class="btn outline" data-edit-transaction="${esc(t.id)}">Edit</button>`:badge(t.status)}])}</section>`}case'withdrawals':{let rows=d.withdrawals||[];return `<div class="section-title"><h1>Withdrawal requests</h1><p>Review pending wallet withdrawal requests.</p></div><div class="alert">Approval records a transaction only; it does not send money to a bank.</div><section class="card">${table(rows,[{label:'Request',key:'id'},{label:'Member',render:w=>esc((d.members||[]).find(m=>m.id===w.memberId)?.name||'—')},{label:'Date',key:'date'},{label:'Method',key:'method'},{label:'Amount',render:w=>`<strong>${money(w.amount)}</strong>`},{label:'Status',render:w=>badge(w.status)},{label:'Edit',render:w=>`<button class="btn outline" data-edit-withdrawal="${esc(w.id)}">Edit request</button>`},{label:'Action',render:w=>w.status!=='Pending'?badge(w.status):`<div style="display:flex;gap:6px"><button class="btn teal" style="padding:7px 9px;font-size:10px" data-admin="withdrawal" data-id="${w.id}" data-status="Approved">Approve</button><button class="btn red" style="padding:7px 9px;font-size:10px" data-admin="withdrawal" data-id="${w.id}" data-status="Rejected">Reject</button></div>`}])}</section>`}case'wallet':return `<div class="section-title"><h1>Wallet balance</h1><p>View your balance and request a withdrawal.</p></div><div class="stats">${(()=>{const earnings=(state.data?.transactions||[]).filter(t=>t.memberId===state.user.id&&['Commission','Sponsor income'].includes(t.type)&&Number(t.amount)>0).reduce((sum,t)=>sum+Number(t.amount||0),0),teamFunds=Number((state.data?.members||[]).find(m=>m.id===state.user.id)?.paymentBalance??state.summary?.paymentBalance)||0;return stat('Available balance',money(teamFunds+earnings),'Team funds + earnings','₹')+stat('Earnings',money(earnings),'Commission and sponsor income','↗','navy')+stat('Team funds',money(teamFunds),'Confirmed team receipts after team remittances','₹','teal')})()}${stat('Minimum withdrawal',money(d.settings?.withdrawalMinimum||500),'Set in settings','↙','navy')}</div><div class="grid-main"><section class="card"><div class="card-head"><div><h2>Request withdrawal</h2><p>Requests remain pending until reviewed by an admin.</p></div></div><form id="withdraw-form"><div class="field"><label>Amount (INR)</label><input required name="amount" type="number" min="${d.settings?.withdrawalMinimum||500}" step="1" placeholder="Minimum ${d.settings?.withdrawalMinimum||500}"></div><div class="field"><label>Payout method</label><select name="method"><option>Bank transfer</option><option>UPI</option></select></div><button class="btn teal">Submit request</button></form></section><section class="card"><div class="card-head"><h2>Withdrawal requests</h2></div>${table(d.withdrawals||[],[{label:'Date',key:'date'},{label:'Amount',render:w=>money(w.amount)},{label:'Status',render:w=>badge(w.status)}])}</section></div>`;case'referrals':return `<div class="section-title"><h1>Referral network</h1><p>Members you have directly invited.</p></div>${referralCard()}<section class="card">${memberTable((d.members||[]).filter(m=>m.sponsor===state.user.id))}</section>`;case'products':return `<div class="section-title"><h1>Manage products</h1><p>Products available in the member store.</p></div><section class="card"><div class="card-head"><div><h2>Product catalogue</h2><p>Add an item to the workspace catalogue.</p></div><button class="btn teal" data-action="add-product">＋ Add product</button></div>${table(d.products||[],[{label:'Product',render:p=>`<span class="product-table-cell">${(p.imageData||p.imageUrl)?`<img src="${esc(p.imageData||p.imageUrl)}" alt="">`:'<span class="product-table-thumb">▣</span>'}<span><strong>${esc(p.name)}</strong><br><small>${esc(p.description||'')}</small></span></span>`},{label:'Category',key:'category'},{label:'Price',render:p=>money(p.price)},{label:'Stock',key:'stock'},{label:'Status',render:p=>badge(p.active?'Active':'Inactive')},{label:'Edit',render:p=>`<button class="btn outline" data-edit-product="${esc(p.id)}">Edit details</button>`}])}</section>`;case'settings':case'payplan':return extraPage(state.page);case'profile':return extraPage('profile');case'getting-started':return `<div class="section-title"><h1>Getting started</h1><p>A simple guide to your member portal.</p></div><section class="card"><div class="activity">${[['1','Review your profile','Check your member details and sponsor.'],['2','Share your invitation link','Invite people you know and answer their questions.'],['3','Explore the store','Browse products and place an order.'],['4','Learn your network','Open genealogy to view your 5 × 5 member genealogy.']].map(([i,t,d])=>`<div class="activity-row"><div class="activity-dot">${i}</div><div class="activity-main"><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div></section>`;case'points':case'kyc':case'epin':case'downloads':case'content':case'banner':case'newsletter':case'rewards':case'notifications':case'ranks':case'payments':case'groups':case'language':case'terms':case'support':case'feedback':return extraPage(state.page);default:return dashboard()}}
function extraPage(page){
  const d=state.data||{},m=d.modules||{},admin=state.user.role==='admin';
  const heading=headings[page]||page;
  const members=d.members||[];
  const rows=d.transactions||[];
  const field=(label,name,value='',type='text')=>`<div class="field"><label>${label}</label>${type==='password'?`<div class="password-wrap"><input name="${name}" type="password" value="${esc(value)}" autocomplete="${name=== 'currentPassword'?'current-password':'new-password'}"><button class="password-toggle" type="button" data-toggle-password aria-label="Show password" title="Show password"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div>`:`<input name="${name}" type="${type}" value="${esc(value)}"></div>`}`;
  switch(page){
    case'edit-member':{
      if(!admin)return `<div class="section-title"><h1>Edit member</h1><p>Administrator access is required.</p></div>`;
      const member=members.find(x=>x.id===state.editMemberId&&x.role==='member');
      if(!member)return `<div class="section-title"><h1>Member not found</h1><p>The account may have been removed.</p></div><button class="btn outline" data-page="members">Back to members</button>`;
      const downline=new Set([member.id]);let changed=true;while(changed){changed=false;for(const x of members){if(downline.has(x.sponsor)&&!downline.has(x.id)){downline.add(x.id);changed=true}}}
      const matrixDownline=new Set([member.id]);let matrixChanged=true;while(matrixChanged){matrixChanged=false;for(const x of members){if(matrixDownline.has(matrixParentOf(x))&&!matrixDownline.has(x.id)){matrixDownline.add(x.id);matrixChanged=true}}}
      const matrixCurrent=matrixParentOf(member)||'';
      const matrixParents=members.filter(x=>x.role==='member'&&!matrixDownline.has(x.id)&&(x.status==='Active'||x.id===matrixCurrent)&&members.filter(y=>y.id!==member.id&&(matrixParentOf(y))===x.id).length<5);
      const matrixParentOptions=matrixParents.map(x=>`<option value="${esc(x.id)}" ${x.id===matrixCurrent?'selected':''}>${esc(x.name)} · ${esc(x.id)} · ${5-members.filter(y=>y.id!==member.id&&(matrixParentOf(y))===x.id).length} open</option>`).join('');
      const parents=members.filter(x=>x.role==='member'&&!downline.has(x.id)&&(x.status==='Active'||x.id===member.sponsor));
      const parentOptions=parents.map(x=>`<option value="${esc(x.id)}" ${member.sponsor===x.id?'selected':''}>${esc(x.name)} · ${esc(x.id)}${x.status==='Active'?'':' · '+esc(x.status)}</option>`).join('');
      return `<div class="section-title"><h1>Edit member details</h1><p>Update account details, referral sponsor, network placement, status or wallet.</p></div><div class="alert">Member ID stays fixed so existing orders and transactions remain linked. A wallet balance change creates an adjustment entry in transaction history. Leave the password blank to keep the current one.</div><section class="card"><div class="card-head"><div><h2>${esc(member.name)}</h2><p>Member ID · ${esc(member.id)} · Role: Member</p></div><span class="pill">${esc(member.status.toUpperCase())}</span></div><form id="edit-member-form" class="edit-member-form"><input type="hidden" name="id" value="${esc(member.id)}"><div class="form-row">${field('Full name','name',member.name)}${field('Username','username',member.username)}</div><div class="form-row">${field('Email address','email',member.email||'','email')}${field('Join date','joined',member.joined||new Date().toISOString().slice(0,10),'date')}</div><div class="field"><label for="edit-member-matrix-parent">Member head (genealogy parent and referrer)</label><select name="matrixParent" id="edit-member-matrix-parent"><option value="" ${matrixCurrent?'':'selected'}>Top-level / no matrix parent</option>${matrixParentOptions}</select></div><div class="form-row"><div class="field"><label for="edit-member-status">Account status</label><select name="status" id="edit-member-status">${['Active','Pending','Inactive'].map(x=>`<option ${member.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div>${field('Set a new password (optional)','password','','password')}<div class="action-row"><div id="edit-member-error" class="form-message product-form-message" role="alert" hidden></div><button class="btn teal" type="submit" data-save-member-edit>Save member changes</button><button class="btn outline" type="button" data-page="members">Cancel</button></div></form></section>`;
    }
    case'commission':{
      const active=members.filter(x=>x.role==='member'&&x.status==='Active');const payouts=rows.filter(x=>x.type==='Commission'||x.type==='Sponsor income');const selected=active.find(x=>x.id===state.commissionPrefillMember)||active[0],selectedTarget=Number(state.commissionPrefillLevel)||2,initialEligibility=selected?commissionEligibility(selected.id,selectedTarget):{positions:0,required:5**selectedTarget,eligible:false,alreadySent:false},initialAmount=commissionAmountForLevel(selectedTarget),initialRate=commissionRates[selectedTarget]||0,shared=(members.find(x=>x.role==='member'&&/SIVANANDHAM/i.test(x.name||''))||{}).paymentBalance||0;
      return `<div class="section-title"><h1>Send commission</h1><p>Pay each head for the matrix level they have completed below their own position.</p></div><div class="alert">Level income = 5 × 5 matrix positions at that depth × ₹3,000 × the fixed level rate. Level 1 is 0%; Level 2 · 2%; Level 3 · 1.6666666666667%; Level 4 · 1%; Level 5 · 0.5%. Sponsor income is ₹300 for each of the first five direct members (₹1,500 total). Payouts unlock automatically when five ₹3,000 base payments and the ₹3,000 head contribution total ₹18,000.</div><section class="card"><div class="card-head"><div><h2>Level income</h2><p>Select a member and the completed matrix level below them.</p></div><span class="pill">${active.length} ACTIVE MEMBERS</span></div><form id="commission-form"><div class="field"><label for="commission-member">Member head</label><select name="memberId" id="commission-member" required>${active.map(x=>`<option value="${esc(x.id)}" ${selected?.id===x.id?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select></div><div class="field"><label for="commission-target-level">Completed level below this member</label><select name="level" id="commission-target-level">${[2,3,4,5].map(level=>`<option value="${level}" ${selectedTarget===level?'selected':''}>Level ${level} · ${5**level} members · ${commissionRates[level]}%</option>`).join('')}</select></div><div class="form-row"><div class="field"><label>Level progress</label><div class="commission-balance" id="commission-level">Level ${selectedTarget} · ${initialEligibility.positions.toLocaleString('en-IN')} / ${initialEligibility.required.toLocaleString('en-IN')} positions</div></div><div class="field"><label>Commission rate</label><div class="commission-balance" id="commission-rate">${initialRate}%</div></div></div><div class="form-row"><div class="field"><label>Calculation base</label><div class="commission-balance" id="commission-base">${money(3000)} × ${initialEligibility.required.toLocaleString('en-IN')} members</div></div><div class="field"><label for="commission-amount">Commission amount</label><input id="commission-amount" name="amount" type="number" value="${initialAmount.toFixed(2)}" readonly aria-readonly="true"></div></div><div class="field"><label>Shared admin / AGS wallet</label><div class="commission-balance" id="commission-balance">${money(shared)}</div></div><div class="field"><label for="commission-note">Reason / note</label><input id="commission-note" name="note" maxlength="180" placeholder="Level ${selectedTarget} income"></div><p id="commission-hint" class="help-copy">${initialEligibility.alreadySent?'This level income was already sent.':!initialEligibility.remittanceReceived?'Automatic eligibility needs five ₹3,000 base payments plus the ₹3,000 head contribution.':initialEligibility.positions<initialEligibility.required?`Complete all ${initialEligibility.required} positions at this level below this head.`:`Eligible: ${initialEligibility.required} × ₹3,000 × ${initialRate}% = ${money(initialAmount)}.`}</p><button id="commission-submit" class="btn teal" ${initialEligibility.eligible&&shared>=initialAmount?'':'disabled'}>${initialEligibility.eligible&&shared>=initialAmount?`Send ${money(initialAmount)} Level ${selectedTarget} income`:'Not eligible yet'}</button></form></section><section class="card"><div class="card-head"><div><h2>Income history</h2><p>Sponsor and level income credited to member wallets.</p></div><button class="btn outline" data-page="transactions">View all transactions</button></div>${table(payouts.slice(0,20),[{label:'Date',key:'date'},{label:'Member',render:x=>`<strong>${esc(members.find(a=>a.id===x.memberId)?.name||x.memberId)}</strong><br><small>${esc(x.memberId)}</small>`},{label:'Details',render:x=>esc(x.description)},{label:'Amount',render:x=>`<strong class="positive">+${money(x.amount)}</strong>`},{label:'Status',render:x=>badge(x.status)}])}</section>`;
    }
    case'add-member':{
      if(!admin)return `<div class="section-title"><h1>Add member</h1><p>Admin access is required to create member accounts.</p></div>`;
      const activeMembers=members.filter(x=>x.role==='member'&&x.status==='Active');
      const matrixParents=members.filter(x=>x.role==='member'&&x.status==='Active'&&members.filter(y=>(matrixParentOf(y))===x.id).length<5);
      const rootMember=members.find(x=>x.role==='member'&&!matrixParentOf(x));const matrixDepthOf=member=>{let depth=0,parent=matrixParentOf(member);const seen=new Set([member.id]);while(parent){if(seen.has(parent))return 999;seen.add(parent);const ancestor=members.find(x=>x.id===parent);if(!ancestor)break;depth++;parent=matrixParentOf(ancestor)}return depth};const matrixDefault=matrixParents.find(x=>x.id===state.matrixPrefillParent)||matrixParents.slice().sort((a,b)=>matrixDepthOf(a)-matrixDepthOf(b)||members.indexOf(a)-members.indexOf(b))[0];
      return `<div class="section-title section-title-action"><div><h1>Create a member account</h1><p>Add a member in this open position. Referral ID/link and member head are prefilled from the genealogy selection.</p></div><span class="pill">ADMIN · MEMBER SETUP</span></div><form id="add-member-form" class="member-create-form"><div class="member-create-grid"><section class="card member-create-card"><div class="card-head"><div><h2>Account details</h2><p>Set up the member’s login and contact information.</p></div><span class="member-step">01</span></div><div class="member-form-grid"><div class="field"><label for="new-member-name">Full name</label><input id="new-member-name" name="name" required minlength="2" maxlength="80" placeholder="Enter the member’s name"></div><div class="field"><label for="new-member-username">Username</label><input id="new-member-username" name="username" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" placeholder="3–24 letters, numbers or _"><small>Used to sign in.</small></div><div class="field"><label for="new-member-email">Email address <span class="optional-label">Optional</span></label><input id="new-member-email" name="email" type="email" maxlength="160" placeholder="name@example.com"></div><div class="field"><label for="new-member-password">Temporary password</label><div class="password-wrap"><input id="new-member-password" name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="At least 8 characters"><button class="password-toggle" type="button" data-toggle-password aria-label="Show password" title="Show password"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div><small>The member can change it after signing in.</small></div></div><div class="form-message product-form-message" id="add-member-error" role="alert" hidden></div><div class="member-create-actions"><button class="btn teal" type="submit" data-save-new-member>Create member account</button><button class="btn outline" type="button" data-page="members">Cancel</button></div></section><aside class="card member-placement-card"><div class="card-head"><div><h2>Referral &amp; placement</h2><p>Choose one head for both referral and genealogy placement.</p></div><span class="member-step">02</span></div><div class="field"><label for="new-member-referral">Referral link or member ID</label><div class="member-reference-control"><input id="new-member-referral" name="referralReference" placeholder="Paste a referral link or enter MLM-1001"><button type="button" class="btn outline" data-resolve-member-ref>Find member</button></div><small id="new-member-referral-hint" class="field-hint">You can paste a SORGAM invite link or enter a member ID.</small></div><div class="field"><label for="new-member-sponsor">Member head (genealogy parent and referrer)</label><select name="matrixParent" id="new-member-sponsor"><option value="" ${!matrixDefault?'selected':''} ${rootMember?'disabled':''}>Primary member head / single root</option>${matrixParents.map(x=>`<option value="${esc(x.id)}" ${matrixDefault?.id===x.id?'selected':''}>${esc(x.name)} · ${esc(x.id)} · ${5-members.filter(y=>(matrixParentOf(y))===x.id).length} open</option>`).join('')}</select><small>New members are placed under this head in the 5 × 5 genealogy.</small></div><div class="field"><label for="new-member-status">Account status</label><select name="status" id="new-member-status"><option value="Active">Active</option><option value="Pending">Pending approval</option></select></div></div><div class="placement-note">The selected head is saved as both the member referrer and genealogy parent.</div></aside></div></form>`;
    }
    case'requests':{const requests=d.feedback||[];return `<div class="section-title"><h1>${admin?'Member requests inbox':'My requests'}</h1><p>${admin?'Review requests submitted from member accounts.':'Send a request and track its status here.'}</p></div>${admin?`<section class="card"><div class="card-head"><div><h2>Incoming requests</h2><p>${requests.filter(x=>x.status!=='Resolved').length} need attention</p></div></div>${table(requests,[{label:'Date',key:'date'},{label:'Member',render:r=>`<strong>${esc(r.name)}</strong><br><small>${esc(r.memberId)}</small>`},{label:'Topic',key:'category'},{label:'Request',render:r=>esc(r.message)},{label:'Status',render:r=>badge(r.status)},{label:'Action',render:r=>r.status==='Resolved'?'<span class="badge">Done</span>':`<button class="btn teal" data-request="${r.id}" data-status="${r.status==='Received'?'In progress':'Resolved'}">${r.status==='Received'?'Start review':'Resolve'}</button>`}])}</section>`:`<section class="card"><div class="card-head"><h2>New request</h2></div><form id="feedback-form"><div class="field"><label>Request type</label><select name="category"><option>Support request</option><option>Order question</option><option>Profile correction</option><option>KYC question</option><option>Product question</option><option>Suggestion</option></select></div><div class="field"><label>What do you need help with?</label><textarea name="message" rows="4" maxlength="2000" required></textarea></div><button class="btn teal">Submit request</button></form></section><section class="card"><div class="card-head"><h2>Your request history</h2></div>${table(requests,[{label:'Date',key:'date'},{label:'Topic',key:'category'},{label:'Request',render:r=>esc(r.message)},{label:'Status',render:r=>badge(r.status)}])}</section>`}`}
    case'readme':return `<div class="section-title"><h1>How to use SORGAM</h1><p>A quick guide for member and administrator portals.</p></div><div class="guide-grid"><section class="card"><h2>Member portal</h2><ol><li>Sign in with your member username and password.</li><li>Open Store, choose a product, and place an order. It will appear in My Orders and Transaction History.</li><li>Use My Requests to contact the admin and track request status.</li><li>Open Genealogy View to explore your 5 × 5 matrix. drag the background to pan, use the mouse wheel or +/− to zoom, and choose Fit all to see the whole tree.</li><li>Use Wallet Balance to submit a withdrawal request.</li><li>Update your contact details in Profile; download reports and your referral banner from Downloads and My Banner.</li></ol></section><section class="card"><h2>Admin portal</h2><ol><li>Sign in with your administrator username and password.</li><li>Use Manage Members to review accounts and Edit details to change saved member information, parent positions, status, wallet, or password. Add Member lets you select one head for both referral and genealogy placement. Click any open matrix plus to add a new member or place an existing member by ID/username. Drag the tree background to pan, use the wheel or +/− to zoom, and choose Fit all for an overview.</li><li>Review Member Requests and Withdrawal Requests; change their status from the action buttons.</li><li>Use Sales History or All Orders to review orders from every member.</li><li>Use Send Commission to credit an active member’s member wallet. Manage products, KYC statuses, ePins, notices, content, payment display options, groups and settings from the sidebar.</li></ol></section></div><section class="card"><h2>About this workspace</h2><p class="help-copy">The workspace starts with the administrator account only. Products, orders, transactions, withdrawals, member requests, and network members start empty. Create the first member from Manage Members or Genealogy. The site does not send money, charge a payment method, send email, or calculate real commissions.</p><div class="action-row"><button class="btn outline" data-page="getting-started">Member getting-started guide</button><button class="btn outline" data-page="support">Open help &amp; support</button></div></section>`;
    case'profile':return `<div class="section-title"><h1>My profile</h1><p>Keep your account details up to date.</p></div><section class="card"><div class="card-head"><h2>Account information</h2>${badge(state.user.status)}</div><form id="profile-form"><div class="profile-photo-control"><img id="profile-photo-preview" src="${esc(state.user.profilePhoto||'/images/sorgam-logo.png')}" alt="Profile photo preview"><div><label for="profile-photo-input">Profile photo</label><input id="profile-photo-input" name="profilePhotoFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small>Upload a square profile photo (max 1.3 MB).</small></div></div>${field('Full name','name',state.user.name)}${field('Email address','email',state.user.email||'','email')}${state.user.role==='admin'?`<div class="form-divider"><h3>Administrator sign-in</h3><p>Change the username or password used to sign in.</p></div>${field('Admin username','username',state.user.username)}${field('Current password','currentPassword','','password')}${field('New password','newPassword','','password')}<small>Leave the new password blank to keep the current one. Enter your current password to save sign-in changes. New passwords must have at least 8 characters.</small>`:''}<button class="btn teal">Save profile</button></form><div class="profile-meta"><span>Account ID <strong>${esc(state.user.id)}</strong></span>${state.user.role==='member'?`<span>Sponsor <strong>${esc(state.user.sponsor||'Top-level account')}</strong></span>`:''}<span>Joined <strong>${esc(state.user.joined)}</strong></span></div></section>`;
    case'points':{const earned=rows.filter(x=>x.amount>0);const points=earned.reduce((n,x)=>n+Math.floor(x.amount/100),0);return `<div class="section-title"><h1>Point history</h1><p>Points are estimated from positive transactions.</p></div><div class="stats">${stat('Points',points,'₹100 positive entry = 1 point','✦')}${stat('Point entries',earned.length,'Recorded entries','▤','','transactions')}</div><section class="card">${table(earned,[{label:'Date',key:'date'},{label:'Transaction',key:'id'},{label:'Description',render:x=>`<strong>${esc(x.description)}</strong>`},{label:'Points',render:x=>Math.floor(x.amount/100)}])}</section>`}
    case'kyc':{const kyc=m.kyc||[];return `<div class="section-title"><h1>Manage KYC</h1><p>Review sample verification entries. No identity documents are collected in this workspace.</p></div><section class="card">${table(kyc.map(k=>({...k,member:members.find(x=>x.id===k.memberId)})),[{label:'Member',render:k=>`<strong>${esc(k.member?.name||k.memberId)}</strong>`},{label:'Member ID',key:'memberId'},{label:'Submitted',key:'submitted'},{label:'Status',render:k=>badge(k.status)},{label:'Review',render:k=>k.status==='Pending'?`<div class="action-row"><button class="btn teal" data-kyc="${k.memberId}" data-status="Verified">Verify</button><button class="btn orange" data-kyc="${k.memberId}" data-status="Needs update">Needs update</button></div>`:'Reviewed'}])}</section>`}
    case'epin':return `<div class="section-title"><h1>Manage ePin</h1><p>Issue and review registration pins.</p></div><div class="alert">Pins do not activate paid memberships or accept payments.</div><section class="card"><div class="card-head"><div><h2>Pin inventory</h2><p>${(m.pins||[]).filter(x=>x.status==='Available').length} available</p></div><button class="btn teal" data-action="generate-pin">＋ Generate pin</button></div>${table(m.pins||[],[{label:'Pin code',render:x=>`<code>${esc(x.code)}</code>`},{label:'Status',render:x=>badge(x.status)},{label:'Assigned to',key:'assignedTo'}])}</section>`;
    case'downloads':return `<div class="section-title"><h1>Downloads &amp; reports</h1><p>Export records from this workspace.</p></div><div class="stats">${stat('Transactions',rows.length,'Download CSV','⇩','','downloads')}${stat('Orders',(d.orders||[]).length,'Download CSV','⇩','','downloads')}${admin?stat('Members',members.filter(x=>x.role==='member').length,'Admin export only','⇩','','downloads'):''}</div><section class="card"><div class="card-head"><div><h2>Member resources</h2><p>Reference files included in the workspace.</p></div></div><div class="resource-grid">${(m.downloads||[]).map(x=>`<div class="resource-card"><div class="resource-icon">⇩</div><div><strong>${esc(x.name)}</strong><small>${esc(x.format)} · ${esc(x.description)}</small></div></div>`).join('')}</div><div class="action-row export-row"><button class="btn outline" data-export="transactions">Export transaction CSV</button><button class="btn outline" data-export="orders">Export order CSV</button><button class="btn outline" data-export="products">Export product CSV</button>${admin?'<button class="btn outline" data-export="members">Export member CSV</button>':''}</div></section>`;
    case'content':{const c=m.content||{};return `<div class="section-title"><h1>${admin?'Digital content':'Page content'}</h1><p>${admin?'Edit the welcome message shown to members.':'Business update from SORGAM.'}</p></div>${admin?`<section class="card"><form id="content-form">${field('Page title','title',c.title||'Welcome to SORGAM')}<div class="field"><label>Welcome message</label><textarea name="message" rows="5" maxlength="1200">${esc(c.message||'')}</textarea></div><button class="btn teal">Save page content</button></form></section>`:`<section class="card content-preview"><span class="eyebrow">SORGAM COMMUNITY</span><h2>${esc(c.title||'Welcome to SORGAM')}</h2><p>${esc(c.message||'')}</p></section>`}`}
    case'banner':{const link=`${location.origin}/?ref=${encodeURIComponent(state.user.username)}`;return `<div class="section-title"><h1>${admin?'Banner promotion':'My banner'}</h1><p>Share your SORGAM invitation link.</p></div><section class="card"><div class="sorgam-banner" id="sorgam-banner"><span>GROW TOGETHER, NATURALLY</span><h2 class="sorgam-wordmark banner-wordmark">SORGAM</h2><p>Discover our community and member store</p><small>${esc(state.user.name)} · ${esc(state.user.id)}</small></div><div class="link-row">Your referral link</div><div class="referral-box"><code id="ref-link">${esc(link)}</code><button data-action="copy">Copy link</button></div><div class="action-row" style="margin-top:14px"><button class="btn teal" data-action="download-banner">Download banner image</button></div></section>`}
    case'newsletter':{const n=m.newsletter||{};return `<div class="section-title"><h1>Newsletter</h1><p>Prepare a local draft for review. This page does not send emails.</p></div><section class="card"><form id="newsletter-form">${field('Subject','subject',n.subject||'SORGAM community update')}<div class="field"><label>Message</label><textarea name="body" rows="6" maxlength="3000">${esc(n.body||'')}</textarea></div><button class="btn teal">Save newsletter draft</button>${n.savedAt?`<span class="pill" style="margin-left:10px">Saved ${esc(n.savedAt)}</span>`:''}</form></section>`}
    case'rewards':{const points=rows.filter(x=>x.amount>0).reduce((n,x)=>n+Math.floor(x.amount/100),0);const tiers=[['Seedling',0,'Welcome reward'],['Sapling',10,'Community bonus'],['Canopy',30,'Growth milestone'],['Forest',75,'Network milestone']];return `<div class="section-title"><h1>Point rewards</h1><p>Sample progress tiers based on transaction points.</p></div><div class="stats">${stat('Your points',points,'Estimated from entries','✦')}${stat('Next reward',tiers.find(x=>x[1]>points)?.[0]||'Forest','Sample reward tier','🌱','navy')}</div><section class="card"><div class="reward-grid">${tiers.map(([name,need,desc],i)=>`<article class="reward-card ${points>=need?'earned':''}"><span class="reward-plant">${['🌱','🌿','🍃','🌳'][i]}</span><h3>${name}</h3><p>${desc}</p><span class="pill">${need} points</span>${points>=need?'<span class="badge">Reached</span>':''}</article>`).join('')}</div></section>`}
    case'notifications':{const ns=m.notifications||[];return `<div class="section-title"><h1>Notification list</h1><p>${admin?'Publish a notice for members.':'Updates from your SORGAM workspace.'}</p></div>${admin?`<section class="card"><form id="notification-form">${field('Notice title','title')}<div class="field"><label>Message</label><textarea name="message" rows="3" maxlength="600" required></textarea></div><button class="btn teal">Publish notice</button></form></section>`:''}<section class="card"><div class="activity">${ns.map(n=>`<div class="activity-row"><div class="activity-dot">◉</div><div class="activity-main"><strong>${esc(n.title)}</strong><small>${esc(n.message)} · ${esc(n.date)}</small></div>${n.read?'<span class="badge">Read</span>':'<span class="pill">NEW</span>'}</div>`).join('')||'<div class="empty-state">No notices yet.</div>'}</div></section>`}
    case'ranks':{const team=state.summary?.teamCount||members.filter(x=>x.role==='member').length;const ranks=[['Seed','0 members'],['Sprout','5 members'],['Grove','12 members'],['Canopy','25 members']];const current=team>=25?'Canopy':team>=12?'Grove':team>=5?'Sprout':'Seed';return `<div class="section-title"><h1>Member ranks</h1><p>Illustrative ranks based on team size. Configure actual qualification rules before launch.</p></div><div class="rank-current"><span class="rank-leaf">🍃</span><div><small>CURRENT RANK</small><h2>${current}</h2><p>${team} team members shown</p></div></div><section class="card"><div class="rank-grid">${ranks.map((r,i)=>`<article class="rank-card"><span>${['🌱','🌿','🍀','🌳'][i]}</span><strong>${r[0]}</strong><small>${r[1]}</small></article>`).join('')}</div></section>`}
    case'payments':return `<div class="section-title"><h1>Payment options</h1><p>Toggle display-only payment methods in the store.</p></div><div class="alert">No payment is processed by this workspace. These switches only affect the shown configuration.</div><section class="card"><form id="payments-form"><div class="activity">${(m.payments||[]).map((x,i)=>`<label class="setting payment-setting"><span><strong>${esc(x.name)}</strong><small>Configuration only</small></span><input class="toggle" type="checkbox" name="payment-${i}" ${x.enabled?'checked':''}></label>`).join('')}</div><button class="btn teal" style="margin-top:18px">Save payment options</button></form></section>`;
    case'settings':case'payplan':{const s=d.settings||{};return `<div class="section-title"><h1>${page==='payplan'?'Payplan settings':'General settings'}</h1><p>Update the workspace values shown in the member and admin portals.</p></div><div class="alert">These controls change workspace settings only. They do not calculate or issue real commissions.</div><section class="card"><form id="settings-form">${field('Currency code','currency',s.currency||'INR')}${field('Matrix width (slots)','matrixWidth',s.matrixWidth||5,'number')}${field('Matrix depth (levels)','matrixDepth',s.matrixDepth||5,'number')}${field('Referral bonus (INR)','referralBonus',s.referralBonus||0,'number')}${field('Matching rate (%)','matchingRate',s.matchingRate||0,'number')}${field('Minimum withdrawal (INR)','withdrawalMinimum',s.withdrawalMinimum||500,'number')}<button class="btn teal">Save settings</button></form></section>`}
    case'groups':{const groups=m.groups||[];return `<div class="section-title"><h1>Member groups</h1><p>Manage community groups.</p></div><section class="card"><form id="groups-form"><div class="field"><label>Group names (one per line)</label><textarea name="groups" rows="6">${esc(groups.join('\n'))}</textarea></div><button class="btn teal">Save groups</button></form></section><div class="group-grid">${groups.map((g,i)=>`<article class="group-card"><span>${['🌱','🍃','🌳'][i%3]}</span><strong>${esc(g)}</strong><small>${Math.max(1,Math.ceil(members.filter(x=>x.role==='member').length/(i+2)))} members</small></article>`).join('')}</div>`}
    case'language':return `<div class="section-title"><h1>Language</h1><p>Choose the navigation language for this browser.</p></div><section class="card"><div class="field"><label>Portal language</label><select id="language-select"><option value="en" ${state.language!=='ta'?'selected':''}>English</option><option value="ta" ${state.language==='ta'?'selected':''}>தமிழ் (Tamil)</option></select></div><button class="btn teal" data-action="save-language">Apply language</button><p class="help-copy">Your preference is saved on this device. Core navigation labels are translated in Tamil.</p></section>`;
    case'terms':{const terms=m.terms||'SORGAM terms';return `<div class="section-title"><h1>Terms &amp; conditions</h1><p>${admin?'Edit the workspace terms.':'Business information for this workspace.'}</p></div><section class="card">${admin?`<form id="terms-form"><div class="field"><label>Terms text</label><textarea name="terms" rows="8" maxlength="4000">${esc(terms)}</textarea></div><button class="btn teal">Save terms</button></form>`:`<div class="terms-copy">${esc(terms)}</div>`}</section>`}
    case'support':return `<div class="section-title"><h1>Help &amp; support</h1><p>Quick answers for the SORGAM portal.</p></div><div class="faq-grid">${[['How do referrals work?','Share your invitation link; new accounts are stored under the referral account.'],['Are orders paid?','No. Orders and payment methods are simulation records only.'],['How do I view my network?','Open Genealogy View to explore the 5 × 5 member genealogy.'],['Need more help?','Send a local feedback note and the administrator can review it.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><button class="btn teal" data-page="feedback">Send feedback</button>`;
    case'feedback':return `<div class="section-title"><h1>Feedback</h1><p>Send a note to the SORGAM admin workspace.</p></div><section class="card"><form id="feedback-form"><div class="field"><label>Topic</label><select name="category"><option>Portal issue</option><option>Product question</option><option>Suggestion</option><option>Other</option></select></div><div class="field"><label>Your message</label><textarea name="message" rows="4" maxlength="2000" required></textarea></div><button class="btn teal">Submit feedback</button></form></section><section class="card"><div class="card-head"><h2>${admin?'Member feedback':'Your feedback'}</h2></div>${table(d.feedback||[],[{label:'Date',key:'date'},{label:'Member',render:f=>esc(f.name)},{label:'Topic',key:'category'},{label:'Message',render:f=>esc(f.message)},{label:'Status',render:f=>badge(f.status)}])}</section>`;
    default:return `<div class="section-title"><h1>${esc(heading)}</h1><p>SORGAM workspace</p></div><section class="card"><div class="empty-state">This section is not available for this account.</div></section>`;
  }
}
