function drawMatrixLinks(){const view=$('[data-tree-viewport]'),svg=$('[data-tree-svg]',view),world=$('[data-tree-world]',svg);if(!view||!svg||!world)return;const width=1200,height=665,treeWidth=Number(svg.getAttribute('data-world-width'))||width,treeHeight=Number(svg.getAttribute('data-world-height'))||height;svg.setAttribute('viewBox',`0 0 ${view.clientWidth||width} ${view.clientHeight||height}`);if(!state.treeView){const scale=.82;state.treeView={scale,x:(view.clientWidth-treeWidth*scale)/2,y:18}}const apply=()=>{world.setAttribute('transform',`translate(${state.treeView.x} ${state.treeView.y}) scale(${state.treeView.scale})`);const label=$('[data-tree-zoom-label]',view);if(label)label.textContent=`${Math.round(state.treeView.scale*100)}%`};const fit=()=>{const scale=Math.min((view.clientWidth-38)/treeWidth,(view.clientHeight-38)/treeHeight,1);state.treeView={scale,x:(view.clientWidth-treeWidth*scale)/2,y:(view.clientHeight-treeHeight*scale)/2};apply()};view._fitTree=fit;view._zoomTree=(factor,x=view.clientWidth/2,y=view.clientHeight/2)=>{const t=state.treeView,scale=Math.max(.08,Math.min(2.4,t.scale*factor)),ratio=scale/t.scale;t.x=x-(x-t.x)*ratio;t.y=y-(y-t.y)*ratio;t.scale=scale;apply()};if(!view.dataset.panReady){view.dataset.panReady='1';let start=null;view.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY,tx:state.treeView.x,ty:state.treeView.y,moved:false,pointerId:e.pointerId}});view.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>4){if(!start.moved){start.moved=true;state.treeDragMoved=true;view.setPointerCapture(e.pointerId);view.classList.add('is-panning')}}if(start.moved){state.treeView.x=start.tx+dx;state.treeView.y=start.ty+dy;apply()}});const finish=e=>{if(start&&view.hasPointerCapture(e.pointerId))view.releasePointerCapture(e.pointerId);start=null;view.classList.remove('is-panning')};view.addEventListener('pointerup',finish);view.addEventListener('pointercancel',finish);view.addEventListener('click',e=>{if(state.treeDragMoved){e.preventDefault();e.stopPropagation();state.treeDragMoved=false}},true);view.addEventListener('wheel',e=>{e.preventDefault();const r=view.getBoundingClientRect();view._zoomTree(e.deltaY<0?1.12:.89,e.clientX-r.left,e.clientY-r.top)},{passive:false})}apply()}
async function saveProductForm(e){e.preventDefault();const form=e.currentTarget,errorBox=$('#product-form-message'),button=form.querySelector('button[type=submit]');if(errorBox){errorBox.hidden=true;errorBox.textContent=''}if(button){button.disabled=true;button.textContent='Saving…'}try{const payload=Object.fromEntries(new FormData(form));payload.active=form.elements.namedItem('active').checked;let result;try{result=await api('/api/admin/product/save',{method:'POST',body:JSON.stringify(payload)})}catch(err){if(err.status!==404)throw err;result=await api('/api/admin/action',{method:'POST',body:JSON.stringify({type:payload.id?'product-edit':'product',...payload})})}const saved=result.product||{...payload,id:payload.id||`LOCAL-${Date.now()}`};if(state.data){const items=state.data.products||(state.data.products=[]),index=items.findIndex(x=>x.id===saved.id);if(index>=0)items[index]=saved;else items.unshift(saved)}state.page='products';state.editProductId=null;render();toast(payload.id?'Product changes saved.':'Product added to the catalogue.');try{await reload()}catch{toast('Saved successfully. Reload the page to sync the catalogue.')}}catch(err){const box=$('#product-form-message');if(box){box.hidden=false;box.textContent=err.message||'Product could not be saved. Check that the local server is running, then retry.'}toast(err.message||'Product could not be saved.',true);if(button){button.disabled=false;button.textContent=state.editProductId?'Save product changes':'Create product'}}}
