function downloadCsv(kind){const rows=state.data?.[kind]||[];const fields={members:['id','name','username','email','sponsor','status','joined'],orders:['id','memberId','productName','amount','status','date'],transactions:['id','memberId','type','description','amount','status','date'],products:['id','name','category','price','stock']}[kind];if(!fields)return toast('This export is not available.',true);const csv=[fields.join(','),...rows.map(row=>fields.map(key=>`"${String(row[key]??'').replace(/"/g,'""')}"`).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`sorgam-${kind}.csv`;a.click();URL.revokeObjectURL(url);toast(`${kind} CSV downloaded.`)}
function downloadBanner(){const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=600;const ctx=canvas.getContext('2d');const gradient=ctx.createLinearGradient(0,0,1200,600);gradient.addColorStop(0,'#214634');gradient.addColorStop(.62,'#4b7c4d');gradient.addColorStop(1,'#93ad68');ctx.fillStyle=gradient;ctx.fillRect(0,0,1200,600);ctx.fillStyle='rgba(255,255,255,.11)';ctx.beginPath();ctx.arc(1040,100,220,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(1100,470,280,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9e8bb';ctx.font='700 28px Arial';ctx.fillText('GROW TOGETHER, NATURALLY',80,130);ctx.fillStyle='#fff';ctx.font='800 94px Arial';ctx.fillText('SORGAM',76,270);ctx.font='32px Arial';ctx.fillText('Discover our community and member store',82,340);ctx.font='24px Arial';ctx.fillStyle='#e5f0da';ctx.fillText(`${state.user.name} · ${state.user.id}`,82,430);const a=document.createElement('a');a.download='sorgam-member-banner.png';a.href=canvas.toDataURL('image/png');a.click();toast('SORGAM banner downloaded.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-resolve-gene-head]');if(!b)return;const input=document.querySelector('#gene-head-reference'),hint=document.querySelector('#gene-head-reference-hint'),select=document.querySelector('#gene-matrix-parent');if(!input||!select||!hint)return;let token=input.value.trim();try{const u=new URL(token,location.origin);token=u.searchParams.get('ref')||u.searchParams.get('sponsor')||token}catch{}const found=(state.data?.members||[]).find(m=>m.role==='member'&&(m.id.toLowerCase()===token.toLowerCase()||m.username.toLowerCase()===token.toLowerCase()));if(!found){hint.textContent='No member matched that referral link, ID or username.';hint.classList.add('error-text');return}const option=[...select.options].find(o=>o.value===found.id);if(!option){hint.textContent='This member cannot be selected as a head: their position is full or they are inside this member’s downline.';hint.classList.add('error-text');return}select.value=found.id;input.value=found.id;hint.textContent=`Member head found: ${found.name} · ${found.id}`;hint.classList.remove('error-text')});
