document.addEventListener('change',async e=>{if(e.target.id==='product-crop-ratio'){ $('#product-image-ratio').value=e.target.value;productCropDraw();return}if(e.target.id==='product-image-ratio'){productCropDraw();return}if(e.target.id==='product-crop-zoom'){productCrop.zoom=Number(e.target.value)||1;productCropDraw();return}if(e.target.id!=='product-image-file')return;const file=e.target.files?.[0];if(!file)return;try{if(!file.type.startsWith('image/'))throw Error('Choose a JPG, PNG or WebP image.');if(file.size>15*1024*1024)throw Error('Choose an image smaller than 15 MB.');closeProductCrop();productCrop.bitmap=await createImageBitmap(file);productCrop.zoom=1;productCrop.x=0;productCrop.y=0;$('#product-crop-zoom').value='1';$('#product-crop-ratio').value=$('#product-image-ratio').value;$('#product-cropper').hidden=false;productCropDraw()}catch(err){closeProductCrop();toast(err.message||'Could not open that image.',true)}});
document.addEventListener('pointerdown',e=>{if(e.target.id!=='product-crop-canvas'||!productCrop.bitmap)return;productCrop.drag={x:e.clientX,y:e.clientY,originX:productCrop.x,originY:productCrop.y};e.target.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{const canvas=$('#product-crop-canvas');if(!productCrop.drag||!canvas)return;const rect=canvas.getBoundingClientRect();productCrop.x=productCrop.drag.originX+(e.clientX-productCrop.drag.x)*canvas.width/rect.width;productCrop.y=productCrop.drag.originY+(e.clientY-productCrop.drag.y)*canvas.height/rect.height;productCropDraw()});document.addEventListener('pointerup',e=>{if(productCrop.drag){productCrop.drag=null;if(e.target?.hasPointerCapture?.(e.pointerId))e.target.releasePointerCapture(e.pointerId)}});document.addEventListener('click',async e=>{if(e.target.id==='product-cropper'||e.target.closest('[data-cancel-product-crop]')){closeProductCrop();return}if(!e.target.closest('[data-apply-product-crop]'))return;const image=productCrop.bitmap;if(!image)return;const source=$('#product-crop-canvas'),ratio=$('#product-image-ratio').value,[rw,rh]=ratio.split('/').map(Number),out=document.createElement('canvas');out.width=1200;out.height=Math.round(1200*rh/rw);const scale=out.width/source.width;out.getContext('2d').drawImage(image,productCrop.left*scale,productCrop.top*scale,productCrop.drawWidth*scale,productCrop.drawHeight*scale);const button=e.target.closest('[data-apply-product-crop]');button.disabled=true;button.textContent='Applying…';try{const data=await productBlobData(await productBlob(out));$('#product-image-data').value=data;$('#product-image-url').value='';$('#product-image-preview').innerHTML='<img src="'+data+'" alt="Product image preview">';closeProductCrop();toast('Cropped image added. Save product changes to keep it.')}catch(err){toast(err.message,true)}finally{button.disabled=false;button.textContent='Apply crop'}});
function productCropDraw(){const image=productCrop.bitmap,canvas=$('#product-crop-canvas'),ratioSelect=$('#product-image-ratio');if(!image||!canvas||!ratioSelect)return;const [rw,rh]=ratioSelect.value.split('/').map(Number),width=640,height=Math.round(width*rh/rw);const wrap=$('.cropper-canvas-wrap');if(wrap)wrap.style.aspectRatio=`${rw}/${rh}`;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#e8eee8';ctx.fillRect(0,0,width,height);productCrop.base=Math.max(width/image.width,height/image.height);productCrop.drawWidth=image.width*productCrop.base*productCrop.zoom;productCrop.drawHeight=image.height*productCrop.base*productCrop.zoom;const maxX=(productCrop.drawWidth-width)/2,maxY=(productCrop.drawHeight-height)/2;productCrop.x=Math.max(-maxX,Math.min(maxX,productCrop.x));productCrop.y=Math.max(-maxY,Math.min(maxY,productCrop.y));productCrop.left=(width-productCrop.drawWidth)/2+productCrop.x;productCrop.top=(height-productCrop.drawHeight)/2+productCrop.y;ctx.drawImage(image,productCrop.left,productCrop.top,productCrop.drawWidth,productCrop.drawHeight)}
function closeProductCrop(){productCrop.bitmap?.close?.();productCrop.bitmap=null;productCrop.drag=null;$('#product-cropper').hidden=true;$('#product-image-file').value=''}
async function productBlob(canvas){let quality=.84,blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));while(blob&&blob.size>420000&&quality>.35){quality-=.08;blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality))}if(!blob||blob.size>420000)throw Error('The cropped image is too large. Zoom out or choose a smaller source image.');return blob}
