function matrixCalculator(){if(state.user?.role!=='admin')return `<div class="section-title"><h1>Matrix calculator</h1><p>Administrator access is required.</p></div>`;const c=state.matrixCalc||={selling:3000,manufacturing:1000,sponsorRate:0,width:5,levels:5,adminRate:5,tdsRate:2,levelRates:[2,2,2,2,2]};const num=(key,label,max=100000000)=>`<div class="field"><label for="calc-${key}">${label}</label><input id="calc-${key}" data-calc="${key}" type="number" min="0" max="${max}" step="0.01" value="${Number(c[key])||0}"></div>`;const rates=Array.from({length:Number(c.levels)||1},(_,i)=>`<div class="field"><label for="calc-level-${i+1}">Level ${i+1} commission (%)</label><input id="calc-level-${i+1}" data-calc-level="${i}" type="number" min="0" max="100" step="0.01" value="${Number(c.levelRates[i])||0}" placeholder="Level ${i+1} rate"></div>`).join('');return `<div class="section-title"><h1>Matrix calculator</h1><p>Estimate the full 5 × 5 plan using your reference summary.</p></div><div class="alert">Reference defaults: ₹3,000 selling price, ₹1,000 manufacturing cost, five levels, 2% commission at each of five levels, 5% Admin/GST, and 2% TDS. Company-profit calculation follows the PDF reference. Confirm tax treatment with your accountant.</div><div class="matrix-calculator-grid"><section class="card matrix-calculator-inputs"><div class="matrix-calc-heading"><h2>Matrix calculator</h2><span>EDITABLE INPUTS</span></div>${num('selling','Selling cost per product (INR)')}${num('manufacturing','Manufacturing cost per product (INR)')}${num('sponsorRate','Sponsor commission (%)',100)}<div class="form-row"><div class="field"><label for="calc-width">Members per parent</label><select id="calc-width" data-calc="width">${[2,3,4,5].map(x=>`<option value="${x}" ${Number(c.width)===x?'selected':''}>${x} wide</option>`).join('')}</select></div><div class="field"><label for="calc-levels">Matrix levels</label><select id="calc-levels" data-calc="levels">${[1,2,3,4,5].map(x=>`<option value="${x}" ${Number(c.levels)===x?'selected':''}>${x} ${x===1?'level':'levels'}</option>`).join('')}</select></div></div><div class="matrix-calc-rates">${rates}</div>${num('adminRate','Admin / GST deduction from commissions (%)',100)}${num('tdsRate','TDS withholding from commissions (%)',100)}<div class="matrix-calc-note">Each level rate is applied to all matrix members at that level and below, as in the supplied summary. Member counts assume a completely filled matrix.</div></section><section class="card matrix-calculator-summary"><div class="matrix-calc-heading"><h2>Summary</h2><span>FULL MATRIX SCENARIO</span></div><div id="matrix-calc-summary" aria-live="polite"></div></section></div>`}
function matrixPie(values){const colors=['#9f4d61','#e99578','#20b89a','#f6a7b5','#df3348','#29a84b'],total=values.reduce((n,x)=>n+x.value,0);if(!total)return '<div class="matrix-pie-empty">Enter a selling cost to see the allocation chart.</div>';let angle=-Math.PI/2;const slices=values.filter(x=>x.value>0).map((x,i)=>{const span=x.value/total*Math.PI*2,start=angle,end=angle+span,cx=130,cy=112,r=88,x1=cx+r*Math.cos(start),y1=cy+r*Math.sin(start),x2=cx+r*Math.cos(end),y2=cy+r*Math.sin(end),large=span>Math.PI?1:0,path=`M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2} Z`;angle=end;return `<path d="${path}" fill="${colors[i%colors.length]}" stroke="#fff" stroke-width="2"><title>${esc(x.label)}: ${money(x.value)} (${(x.value/total*100).toFixed(1)}%)</title></path>`}).join('');const legend=values.map((x,i)=>`<div class="matrix-pie-legend"><i style="background:${colors[i%colors.length]}"></i><span>${esc(x.label)}</span><strong>${money(x.value)}</strong></div>`).join('');return `<div class="matrix-pie-layout"><svg class="matrix-pie" viewBox="0 0 260 224" role="img" aria-label="Calculated cost and income allocation pie chart">${slices}<circle cx="130" cy="112" r="43" fill="#fff"/><text x="130" y="108" text-anchor="middle" class="matrix-pie-total-label">TOTAL</text><text x="130" y="128" text-anchor="middle" class="matrix-pie-total">${money(total)}</text></svg><div class="matrix-pie-legend-list">${legend}</div></div>`}
function calculateMatrixSummary(){const c=state.matrixCalc||{},unitSelling=Math.max(0,Number(c.selling)||0),unitManufacturing=Math.max(0,Number(c.manufacturing)||0),width=Math.max(2,Math.min(5,Number(c.width)||5)),levels=Math.max(1,Math.min(5,Number(c.levels)||1)),counts=Array.from({length:levels},(_,i)=>width**(i+1)),positions=counts.reduce((a,b)=>a+b,0),sales=unitSelling*positions,manufacturing=unitManufacturing*positions,sponsor=sales*Math.min(100,Number(c.sponsorRate)||0)/100,levelBases=counts.map((_,i)=>counts.slice(i).reduce((a,b)=>a+b,0)*unitSelling),levelAmounts=levelBases.map((base,i)=>base*Math.min(100,Number(c.levelRates?.[i])||0)/100),matrix=levelAmounts.reduce((a,b)=>a+b,0),grossCommission=sponsor+matrix,admin=grossCommission*Math.min(100,Number(c.adminRate)||0)/100,tds=grossCommission*Math.min(100,Number(c.tdsRate)||0)/100,net=Math.max(0,grossCommission-admin-tds),companyProfit=sales-manufacturing-net,summary=$('#matrix-calc-summary');if(!summary)return;const allocation=[{label:'Manufacturing cost',value:manufacturing},{label:'Member income after deductions',value:net},{label:'TDS withheld',value:tds},{label:'Admin / GST deduction',value:admin},{label:'Company profit (PDF method)',value:Math.max(0,companyProfit)}];summary.innerHTML=`<div class="matrix-calc-kpis"><div><span>Total selling collected</span><strong>${money(sales)}</strong><small>${positions.toLocaleString('en-IN')} members × ${money(unitSelling)} per member</small></div><div><span>Company profit (PDF method)</span><strong class="${companyProfit>=0?'positive':'negative'}">${money(companyProfit)}</strong><small>${sales?`${(companyProfit/sales*100).toFixed(1)}% of collected sales`:'Enter a selling cost to calculate'}</small></div></div><div class="matrix-pie-wrap"><h3>Reference figures</h3>${matrixPie(allocation)}</div><div class="matrix-calc-lines"><div><span>Total members in filled matrix</span><strong>${positions.toLocaleString('en-IN')}</strong></div><div><span>Total selling collected</span><strong>${money(sales)}</strong></div><div><span>Total manufacturing cost</span><strong>− ${money(manufacturing)}</strong></div><div><span>Sponsor commission (${Number(c.sponsorRate)||0}%)</span><strong>− ${money(sponsor)}</strong></div>${counts.map((count,i)=>`<div><span>Level ${i+1} · ${count.toLocaleString('en-IN')} members; rate applies to ${levelBases[i]/(unitSelling||1)||0} members at this level and below (${Number(c.levelRates?.[i])||0}%)</span><strong>− ${money(levelAmounts[i])}</strong></div>`).join('')}<div><span>Gross commissions</span><strong>− ${money(grossCommission)}</strong></div><div><span>Admin / GST deduction (${Number(c.adminRate)||0}%)</span><strong>${money(admin)}</strong></div><div><span>TDS withheld (${Number(c.tdsRate)||0}%)</span><strong>${money(tds)}</strong></div><div><span>Member income after deductions</span><strong>${money(net)}</strong></div><div><span>Company profit (PDF method)</span><strong>${money(companyProfit)}</strong></div></div><div class="matrix-calc-foot">PDF method: company profit = selling profit − member income after Admin/GST and TDS deductions. Because those deductions are also listed separately, the reference figures overlap and the pie is a comparison of reported figures, not a reconciled allocation. Tax settings are estimates, not tax advice.</div>`}
document.addEventListener('input',e=>{if(!e.target.matches('[data-calc],[data-calc-level]'))return;const c=state.matrixCalc;if(e.target.hasAttribute('data-calc-level'))c.levelRates[Number(e.target.dataset.calcLevel)]=Number(e.target.value)||0;else c[e.target.dataset.calc]=Number(e.target.value)||0;calculateMatrixSummary()});document.addEventListener('change',e=>{if(e.target.id==='calc-levels'){state.matrixCalc.levels=Number(e.target.value)||1;render();calculateMatrixSummary()}else if(e.target.matches('[data-calc]')){state.matrixCalc[e.target.dataset.calc]=Number(e.target.value)||0;calculateMatrixSummary()}});document.addEventListener('click',e=>{if(e.target.closest('[data-page="matrix-calculator"]')){setTimeout(calculateMatrixSummary,0)}});
document.addEventListener('click',async e=>{const open=e.target.closest('[data-reset-open]');if(open){$('#reset-dialog')?.showModal();return}if(e.target.closest('[data-reset-close]')){$('#reset-dialog')?.close();return}const button=e.target.closest('[data-reset-mode]');if(!button)return;const mode=button.dataset.resetMode,label=mode==='everything'?'Reset everything':'Reset transactions';const warning=mode==='everything'?'This permanently removes all members and workspace data except your administrator account. Continue?':'This clears all transactions, payment records, withdrawals, and member wallet balances. Member accounts, products, and orders stay. Continue?';if(!confirm(warning))return;button.disabled=true;try{const result=await api('/api/admin/reset',{method:'POST',body:JSON.stringify({mode})});$('#reset-dialog')?.close();const c=result.counts;toast(mode==='everything'?`Workspace reset. Removed ${c.members} members, ${c.products} products, and ${c.orders} orders.`:`Transactions reset. Cleared ${c.transactions} transactions, ${c.memberPayments} payment records, and ${c.withdrawals} withdrawals. Wallets are zero.`);await reload()}catch(err){toast(err.message||'Reset failed.',true);button.disabled=false}});
